import{_ as t,c as n,o,ag as s}from"./chunks/framework.Cycwnjj0.js";const r="/assets/geotracking-api-settings-from-azonpress-dashboard.hoc_4pzy.webp",a="/assets/generate-license-keys-maxmind.D6i3yxFT.webp",i="/assets/confirm-generation-of-new-license-key-maxmind.BU_7e4DZ.webp",g="/assets/new-license-key-successfully-created-maxmind.DQkySISe.webp",c="/assets/update-the-license-key-in-azonpress.CMWKEtN4.webp",y=JSON.parse('{"title":"Geo Tracking (Targeting) Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuring-amazon-api/geo-tracking-targeting-settings.md","filePath":"guide/configuring-amazon-api/geo-tracking-targeting-settings.md"}'),p={name:"guide/configuring-amazon-api/geo-tracking-targeting-settings.md"};function l(h,e,d,m,u,f){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="geo-tracking-targeting-settings" tabindex="-1">Geo Tracking (Targeting) Settings <a class="header-anchor" href="#geo-tracking-targeting-settings" aria-label="Permalink to &quot;Geo Tracking (Targeting) Settings&quot;">​</a></h1><p>AzonPress allows you to easily re-route the Amazon links to different stores based on the user&#39;s location and offers a GeoTracking Settings option to track your customers&#39; locations using this. This article will guide you through the process of <strong>configuring</strong> custom <strong>Geo Tracking</strong> in <strong>AzonPress</strong>.</p><h2 id="geo-tracking-api-settings-in-azonpress" tabindex="-1">Geo Tracking API Settings in AzonPress <a class="header-anchor" href="#geo-tracking-api-settings-in-azonpress" aria-label="Permalink to &quot;Geo Tracking API Settings in AzonPress&quot;">​</a></h2><p>To learn how to <strong>configure</strong> custom <strong>GeoTracking API</strong> in <strong>AzonPress</strong>, follow the steps with the screenshots below –</p><p>First, go to <strong>Settings</strong> from your <strong>AzonPress Navbar</strong> and open the <strong>GeoTracking Settings</strong> option from the left sidebar.</p><p>Now, here you have to give the <strong>MaxMind API Key</strong> to enable your GEO Tracking/Targeting.</p><p><img src="'+r+'" alt="GeoTracking API settings from AzonPress Dashboard"></p><h2 id="how-to-get-maxmind-geo-ip-api-license-key" tabindex="-1">How To Get Maxmind GEO-IP API/License Key <a class="header-anchor" href="#how-to-get-maxmind-geo-ip-api-license-key" aria-label="Permalink to &quot;How To Get Maxmind GEO-IP API/License Key&quot;">​</a></h2><p>To learn how to get the Maxmind GEO-IP API Key, follow the steps with the screenshots below –</p><p>First, log in to your Maxmind Account or sign up here for free.</p><p>After logging into the <strong>MaxMind account</strong>, go to <strong>Manage Licence Key</strong> from the left sidebar, and click on the <strong>Generate new license Key</strong> button.</p><p><img src="'+a+'" alt="Generate License Keys from MaxMind"></p><p>A confirmation page will come to Generate New Licence Key, click on the <strong>Confirm</strong> button here.</p><p><img src="'+i+'" alt="Confirm generation of new license key in MaxMind"></p><p>Now you will get your <strong>Maxmind API key</strong>. Copy it from here.</p><p><img src="'+g+'" alt="New license key successfully created in MaxMind"></p><h2 id="update-api-key-on-azonpress" tabindex="-1">Update API Key on AzonPress <a class="header-anchor" href="#update-api-key-on-azonpress" aria-label="Permalink to &quot;Update API Key on AzonPress&quot;">​</a></h2><p>Go back to <strong>Settings</strong> from the <strong>AzonPress Navbar</strong> again and open the <strong>GeoTracking Settings</strong> option.</p><p>Now, paste the <strong>API Key</strong> you have <strong>copied from</strong> the <strong>Maxmind</strong> account into the <strong>MaxMind API Key</strong> field and click on the <strong>Update</strong> button.</p><p><img src="'+c+'" alt="Update the license key in AzonPress"></p><p>Now Geo-targeting/tracking will work just fine with AzonPress!</p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',23)])])}const P=t(p,[["render",l]]);export{y as __pageData,P as default};
